using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize(Roles="Admin,Manager")]public class UsersController:Controller{private readonly UserManager<ApplicationUser> _users;private readonly RoleManager<IdentityRole> _roles;private readonly IAuditService _audit;public UsersController(UserManager<ApplicationUser> users,RoleManager<IdentityRole> roles,IAuditService audit){_users=users;_roles=roles;_audit=audit;}public async Task<IActionResult>Index(){var list=await _users.Users.OrderBy(x=>x.Email).ToListAsync();return View(list);}public async Task<IActionResult>Edit(string id){var u=await _users.FindByIdAsync(id);if(u==null)return NotFound();ViewBag.Roles=await _roles.Roles.Select(x=>x.Name!).ToListAsync();ViewBag.CurrentRole=(await _users.GetRolesAsync(u)).FirstOrDefault();return View(u);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(string id,string role,bool isActive){var u=await _users.FindByIdAsync(id);if(u==null)return NotFound();u.IsActive=isActive;await _users.UpdateAsync(u);var old=await _users.GetRolesAsync(u);if(old.Count>0)await _users.RemoveFromRolesAsync(u,old);if(!string.IsNullOrWhiteSpace(role))await _users.AddToRoleAsync(u,role);await _audit.LogAsync("Role Change","User",id,newValue:new{role,isActive});return RedirectToAction(nameof(Index));}}
